	static Stream<Arguments> crashPoints() {
		return Stream.of(
				Arguments.of(Step.PLANNED, 1),
				Arguments.of(Step.SKETCH_INVALIDATED, 1),
				Arguments.of(Step.STATEMENT_BATCH_COMMITTED, 1),
				Arguments.of(Step.STATEMENT_BATCH_COMMITTED, 4),
				Arguments.of(Step.STATEMENTS_REWRITTEN, 1),
				Arguments.of(Step.VALUES_MERGED, 1));
	}

	@ParameterizedTest(name = "crash at {0} #{1}")
	@MethodSource("crashPoints")
	void crashDuringTheMergeIsCompletedOnReopen(Step crashStep, int occurrence) throws Exception {
		LegacyIds legacy = buildLegacyStore();
		LmdbLanguageTagVariantMerge.statementBatchRowsForTesting = 1;
		AtomicInteger reached = new AtomicInteger();
		LmdbLanguageTagVariantMerge.stepObserverForTesting = step -> {
			if (step == crashStep && reached.incrementAndGet() == occurrence) {
				throw new IOException("simulated crash at " + step + " #" + occurrence);
			}
		};

		LmdbStore crashed = new LmdbStore(storeDir, config());
		assertThrows(SailException.class, crashed::init, "the simulated crash must abort the open");
		assertEquals(occurrence, reached.get(), "fixture: the crash point must be reached");
		assertEquals(StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT, languageTagKey(storeDir),
				"an interrupted merge never records canonical keys");

		LmdbLanguageTagVariantMerge.stepObserverForTesting = null;
		LmdbStore resumed = open();
		try {
			assertEquals(LanguageTagKeyMode.CANONICAL, valueStore(resumed).languageTagKeyMode());
			assertMatchesReference(resumed, "resumed after a crash at " + crashStep + " #" + occurrence);
			assertLosersMerged(resumed, legacy);
		} finally {
			resumed.shutDown();
		}
		assertEquals(StoreProperties.LANGUAGE_TAG_KEY_CANONICAL, languageTagKey(storeDir));

		LmdbStore reopened = open();
		try {
			assertMatchesReference(reopened, "reopened after the resumed merge");
		} finally {
			reopened.shutDown();
		}
	}

	/**
	 * The value-store half of the merge is one transaction unless the value map has to grow mid-way: then the work done
	 * so far is committed early. A crash right after such an early commit must be completed on the next open as well.
	 */
	@ParameterizedTest(name = "crash after value-store merge step {0}")
	@ValueSource(ints = { 1, 2, 3 })
	void crashAfterAnEarlyCommitOfTheValueStoreMergeIsCompletedOnReopen(int step) throws Exception {
		LegacyIds legacy = buildLegacyStore();
		ValueStore.crashAfterLanguageTagMergeStepForTesting = completed -> completed == step;
		LmdbStore crashed = new LmdbStore(storeDir, config());
		assertThrows(SailException.class, crashed::init, "the simulated crash must abort the open");
		ValueStore.crashAfterLanguageTagMergeStepForTesting = null;
		assertEquals(StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT, languageTagKey(storeDir));
		assertEarlyCommit(step, legacy);

		LmdbStore resumed = open();
		try {
			assertEquals(LanguageTagKeyMode.CANONICAL, valueStore(resumed).languageTagKeyMode());
			assertMatchesReference(resumed, "resumed after a crash after value-store merge step " + step);
			assertLosersMerged(resumed, legacy);
		} finally {
			resumed.shutDown();
		}

		LmdbStore reopened = open();
		try {
			assertMatchesReference(reopened, "reopened after the resumed merge");
			assertLosersMerged(reopened, legacy);
		} finally {
			reopened.shutDown();
		}
	}

